INSERT INTO capital_source_profiles (institution_id,capital_types,sectors,geographies,minimum_readiness,instrument_notes,eligibility_notes,evidence_urls) SELECT ip.id,'["debt","dfi","blended_finance"]'::jsonb,'["manufacturing","agriculture","agro_processing","solid_minerals","healthcare","technology","creative","renewable_energy","oil_and_gas","msme"]'::jsonb,'["Nigeria"]'::jsonb,55,'Longer-tenor and concessionary lending, project-based lending, cluster programmes, intervention funds and intermediary channels are part of BOI offerings.','Product-specific eligibility, registration, sector, security and other requirements apply; the platform must verify the current programme before presenting a route as actionable.','["https://www.boi.ng/who-we-serve/msmes/","https://www.boi.ng/who-we-serve/psip/","https://www.boi.ng/products/"]'::jsonb FROM institutional_profiles ip WHERE ip.organization_name='Bank of Industry' AND NOT EXISTS (SELECT 1 FROM capital_source_profiles csp WHERE csp.institution_id=ip.id);